    {
      "service": "ts-auth-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name IN ('POST /api/v1/users/login','UserController.getToken') GROUP BY ALL ORDER BY n DESC",
          "claim": "In the incident, every ts-auth-service login span (about 1532) is Error, with login returning HTTP 500."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='ts-auth-service' AND level='SEVERE' GROUP BY ALL",
          "claim": "Auth logs SEVERE JSON parse errors: unrecognized token 'tvfd26' where a Boolean was expected from verification-code."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code st, count(*) n FROM abnormal_traces WHERE service_name='ts-verification-code-service' AND span_name='GET /api/v1/verifycode/verify/{verifyCode}' GROUP BY ALL",
          "claim": "Verification-code verify calls still return HTTP 200 and fast, so the status is intact while the body diverges."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_status_code, attr_http_response_status_code st, count(*) n FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'nor', * FROM normal_traces) WHERE service_name='ts-auth-service' AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "Normal period: login returns 200 with no errors; abnormal period: all login requests error with 500."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code st, count(*) n, quantile_cont(duration/1e6,0.5) med_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/users/login' GROUP BY ALL",
          "claim": "ui-dashboard login requests fail with 500 and multi-second latency, mirroring auth's login errors."
        }
      ]
    }
  ]
}
